function doubleEvens(nums) {
  return nums.filter((n) => n % 2 === 0).map((n) => n * 2);
}

function sum(nums) {
  return nums.reduce((total, n) => total + n, 0);
}

function numericSorted(nums) {
  return nums.slice().sort((a, b) => a - b);
}
